CTE-A06.sql:
SELECT OrderID INTO #Ids FROM ecommerce.Orders;
DELETE FROM #Ids WHERE OrderID IN (5, 10);   -- setup

DECLARE @MaxID int = (SELECT MAX(OrderID) FROM #Ids);

WITH N AS (
    SELECT 1 AS id
    UNION ALL
    SELECT id + 1 FROM N WHERE id < @MaxID
)
SELECT n.id AS MissingID
FROM N AS n
LEFT JOIN #Ids AS i ON i.OrderID = n.id
WHERE i.OrderID IS NULL
OPTION (MAXRECURSION 0);

DROP TABLE #Ids;

